files.styles/main.css:
@page {
  size: A4;
  margin: 25mm 22mm 25mm 22mm;

  @top-center {
    content: string(section);
    font-family: "Inter";
    font-size: 8pt;
    color: #6b7280;
  }

  @bottom-center {
    content: counter(page) " of " counter(pages);
    font-family: "Inter";
    font-size: 8pt;
    color: #6b7280;
  }
}

@page :first {
  @top-center {
    content: none;
  }
}

body {
  font-family: "Inter";
  font-size: 10.5pt;
  line-height: 1.55;
  color: #111827;
}

h1 {
  font-size: 24pt;
  font-weight: 700;
  margin: 0 0 6mm 0;
  string-set: section content();
}

h2 {
  font-size: 15pt;
  font-weight: 700;
  margin: 8mm 0 3mm 0;
  break-after: avoid;
}

h3 {
  font-size: 12pt;
  font-weight: 700;
  margin: 6mm 0 2mm 0;
  break-after: avoid;
}

p {
  margin: 0 0 3mm 0;
  orphans: 3;
  widows: 3;
}

ul, ol {
  margin: 0 0 3mm 0;
  padding-left: 6mm;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 4mm 0;
}

th, td {
  border-bottom: 0.4pt solid #d1d5db;
  padding: 2mm 2mm;
  text-align: left;
}

th {
  font-weight: 700;
  background: #f3f4f6;
}

code {
  font-family: "Inter";
  background: #f3f4f6;
  padding: 0.5mm 1mm;
}

blockquote {
  margin: 3mm 0;
  padding-left: 4mm;
  border-left: 1.2pt solid #d1d5db;
  color: #4b5563;
}

@page {
  size: A4;
  margin: 16mm 16mm 16mm 16mm;
}

body {
  font-family: "Inter";
  font-size: 10pt;
  line-height: 1.4;
  color: #111827;
}

h1 {
  font-size: 20pt;
  font-weight: 700;
  margin: 0;
}

h1 + p {
  font-size: 10.5pt;
  color: #4b5563;
  margin: 1mm 0 5mm 0;
}

h2 {
  font-size: 10pt;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #6b7280;
  margin: 5mm 0 2mm 0;
  border-bottom: 0.5pt solid #d1d5db;
  padding-bottom: 1mm;
  break-after: avoid;
}

p {
  margin: 0 0 2mm 0;
}

ul {
  margin: 0 0 2mm 0;
  padding-left: 5mm;
}

@page {
  size: A4;
  margin: 24mm 24mm 24mm 24mm;

  @bottom-center {
    content: counter(page);
    font-family: "Inter";
    font-size: 8pt;
    color: #6b7280;
  }
}

body {
  font-family: "Source Serif 4";
  font-size: 11.5pt;
  line-height: 1.6;
  color: #1f2937;
}

h1 {
  font-family: "Inter";
  font-size: 22pt;
  font-weight: 700;
  line-height: 1.25;
  margin: 0 0 5mm 0;
}

h2 {
  font-family: "Inter";
  font-size: 14pt;
  font-weight: 700;
  margin: 8mm 0 3mm 0;
  break-after: avoid;
}

h3 {
  font-family: "Inter";
  font-size: 12pt;
  font-weight: 700;
  margin: 6mm 0 2mm 0;
  break-after: avoid;
}

p {
  margin: 0 0 3.5mm 0;
  orphans: 3;
  widows: 3;
}

blockquote {
  font-style: italic;
  margin: 5mm 0;
  padding-left: 5mm;
  border-left: 1.2pt solid #cbd5e1;
  color: #475569;
}

code {
  font-family: "Inter";
  font-size: 0.9em;
  background: #f1f5f9;
  padding: 0.5mm 1mm;
}
